<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">PAYMENT FLOW</div><h1>Initiate Payment</h1><p>Card status and limits are validated server-side before gateway initiation.</p></div></div><div class="panel form-panel"><form method="POST" action="<?php echo e(route('payments.store')); ?>"><?php echo csrf_field(); ?><div class="form-grid"><label class="wide">Business<select id="business" name="business_id" required><?php $__currentLoopData = $businesses; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $b): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($b->id); ?>" data-cards='<?php echo json_encode($b->cards, 15, 512) ?>'><?php echo e($b->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Virtual Card<select id="card" name="card_id" required></select></label><label>Amount (INR)<input name="amount" type="number" step="0.01" min="0.01" required></label><label>Gateway<select name="gateway"><option value="mock">Mock Sandbox</option><option value="razorpay">Razorpay</option><option value="paytm">Paytm</option></select></label></div><div class="notice">Flow: validate card → limits → create payment → gateway checkout → server verification/webhook → transaction ledger.</div><div class="form-actions"><a class="btn secondary" href="<?php echo e(route('payments.index')); ?>">Cancel</a><button class="btn primary">Create Payment</button></div></form></div><script>const b=document.querySelector('#business'),c=document.querySelector('#card');function sync(){const cards=JSON.parse(b.selectedOptions[0].dataset.cards||'[]');c.innerHTML=cards.map(x=>`<option value="${x.id}">${x.reference} · ${x.cardholder_name} · ₹${Number(x.current_usage).toFixed(2)} used</option>`).join('')}b.addEventListener('change',sync);sync();</script><?php $__env->stopSection(); ?>

